{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.monthly_spends_target_remaining as WITH pre_data AS ( select date_trunc(month,order_timestamp::date) as order_month, sum(gross_sales+(case when lower(discount_code) is not null and lower(discount_code) like \'%rms%\' then 0 else discount end)) as mrp_sales, sum(case when lower(discount_code) is not null and lower(discount_code) like \'%rms%\' then 0 else discount end)/(sum(case when lower(discount_code) is not null and lower(discount_code) like \'%rms%\' then 0 else discount end)+sum(gross_sales)) as discount_percentage, sum(case when order_status = \'CANCELLED\' then gross_sales end)/sum(gross_sales) as cancellation_percentage, sum(gross_sales) as gross_sales, sum(case when order_timestamp::date < \'2025-09-22\' and gross_sales / quantity < 999 THEN gross_sales::int * 0.05 when order_timestamp::date < \'2025-09-22\' and gross_sales / quantity >= 999 THEN gross_sales::int * 0.12 when order_timestamp::date >= \'2025-09-22\' and gross_sales / quantity < 2500 THEN gross_sales::int * 0.05 when order_timestamp::date >= \'2025-09-22\' and gross_sales / quantity >= 2500 THEN gross_sales::int * 0.18 end) as tax from snitch_db.maplemonk.fact_items_snitch group by 1 ), spends AS ( select date_trunc(month,date) as order_month, sum(total_spend-160000) as total_spend from (select date,sum(spend)::int as total_spend from snitch_db.maplemonk.marketing_consolidated_snitch group by 1) group by 1 ), returns_data AS ( select date_trunc(\'month\',order_date) as order_month, sum(sales_value)::int as returns_gross from snitch_db.maplemonk.return_fact_items where return_qty > 0 group by 1 ), actuals AS ( select a.*, b.total_spend, coalesce(c.returns_gross,0) as returns_gross, b.total_spend/((gross_sales*(1-cancellation_percentage))-returns_gross) as marekting_percentage, (returns_gross/gross_sales) as return_percentage, gross_sales/total_spend as roas, from pre_data a left join spends b on a.order_month = b.order_month left join returns_data c on a.order_month = c.order_month ), actuals_main_plan as ( SELECT order_month, actual_plan, value FROM ( SELECT order_month, CAST(mrp_sales AS NUMBER(38,2)) AS mrp_sales, CAST(gross_sales AS NUMBER(38,2)) AS gross_sales, CAST(discount_percentage AS NUMBER(38,2)) AS discount_percentage, CAST(total_spend AS NUMBER(38,2)) AS total_spend, CAST(return_percentage AS NUMBER(38,2)) AS return_percentage, CAST(cancellation_percentage AS NUMBER(38,2)) AS cancellation_percentage, CAST(marekting_percentage AS NUMBER(38,2)) AS marekting_percentage, CAST(tax AS NUMBER(38,2)) AS tax, CAST(roas AS NUMBER(38,2)) AS roas, FROM actuals ) UNPIVOT ( value FOR actual_plan IN ( mrp_sales, gross_sales, discount_percentage, total_spend, roas, return_percentage, cancellation_percentage, marekting_percentage, tax ) ) ORDER BY order_month, actual_plan ), target as ( select month, replace(gross_sales,\',\',\'\')/(1-discount_percentage) as mrp_sales, replace(gross_sales,\',\',\'\') as gross_sales, discount_percentage, total_spend, roas, return_percentage, marekting_percentage, cancellation_percentage, from snitch_db.maplemonk.gs_monthly_pnl_shopify_targets ), unpivotedtarget AS ( SELECT month as order_month, target_plan, value, FROM ( SELECT month, CAST(mrp_sales AS NUMBER(38,2)) AS mrp_sales, CAST(gross_sales AS NUMBER(38,2)) AS gross_sales, CAST(discount_percentage AS NUMBER(38,2)) AS discount_percentage, CAST(total_spend AS NUMBER(38,2)) AS total_spend, CAST(roas AS NUMBER(38,2)) AS roas, CAST(return_percentage AS NUMBER(38,2)) AS return_percentage, CAST(marekting_percentage AS NUMBER(38,2)) AS marekting_percentage, CAST(cancellation_percentage AS NUMBER(38,2)) AS cancellation_percentage FROM target ) UNPIVOT ( value FOR target_plan IN ( mrp_sales, gross_sales, discount_percentage, total_spend, roas, return_percentage, marekting_percentage, cancellation_percentage )) ) select a.order_month, a.actual_plan as metrics, a.value as actuals, b.value as target, case when metrics in (\'TOTAL_SPEND\',\'MRP_SALES\',\'GROSS_SALES\') then (b.value-a.value)/(DATEDIFF(day, CURRENT_DATE, LAST_DAY(CURRENT_DATE)) + 1) else null end as remaining_per_day, case when metrics = \'MRP_SALES\' then 1 when metrics = \'GROSS_SALES\' then 2 when metrics = \'TOTAL_SPEND\' then 3 when metrics = \'ROAS\' then 4 when metrics = \'DISCOUNT_PERCENTAGE\' then 5 when metrics = \'RETURN_PERCENTAGE\' then 6 when metrics = \'CANCELLATION_PERCENTAGE\' then 7 when metrics = \'MAREKTING_PERCENTAGE\' then 8 when metrics = \'TAX\' then 9 else null end as ranking from actuals_main_plan a left join unpivotedtarget b on a.order_month = b.order_month and a.actual_plan = b.target_plan ;",
                    "transaction": true
                }
            ) }}
